INSERT INTO programs (id,name,description,outcome_label) VALUES ('nextwave','Next Wave Workshops','School-based safety and emotional wellbeing workshops. Students practice asking for help, recognizing trusted adults, handling conflict, and supporting one another. This educational program is separate from clinical counseling.','Confidence asking for help and identifying support');
